        "bug_count": 0,
        "style_issues": [],
        "corrected_code": None,
        "warnings": []
    }

    if not code or not code.strip():
        result["warnings"].append("No code provided for analysis.")
        return result

    try:
        tree = ast.parse(code)
    except SyntaxError as e:
        result["is_valid_syntax"] = False
        result["overall_status"] = "syntax_error"
        result["issues"].append({
            "type": "syntax_error",
            "severity": "critical",
            "line": e.lineno,
            "description": e.msg,
            "suggestion": "Fix the syntax error at the indicated line."
        })
        return result

    # Analysis State
    defined_vars = set(['__builtins__', 'print', 'len', 'range', 'int', 'str', 'list', 'dict', 'set', 'float', 'sum', 'max', 'min', 'open'])

    # Walk the AST
    for node in ast.walk(tree):
        # 1. Division by Zero
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Div):
            if isinstance(node.right, ast.Constant) and node.right.value == 0:
                result["issues"].append({
                    "type": "runtime_risk",
                    "severity": "high",
                    "line": getattr(node, 'lineno', 0),
                    "description": "Potential division by zero detected.",
                    "suggestion": "Ensure the divisor is not zero before dividing."
                })

        # 2. Undefined Variables (Basic check)
        if isinstance(node, ast.Name):
            if isinstance(node.ctx, ast.Store):
                defined_vars.add(node.id)
            elif isinstance(node.ctx, ast.Load):
                if node.id not in defined_vars:
                    # We only flag this as a risk because of potential imports or global scope
                    result["issues"].append({
                        "type": "logic_risk",
                        "severity": "medium",
                        "line": getattr(node, 'lineno', 0),
                        "description": f"Variable '{node.id}' may be undefined.",
                        "suggestion": "Ensure the variable is defined before use."
                    })

    # Function-specific analysis
    for node in ast.walk(tree):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            # Check for missing return paths
            has_return = False
            for stmt in node.body:
                if isinstance(stmt, ast.Return):
                    has_return = True
                    break
            if not has_return and strict_mode:
                result["issues"].append({
                    "type": "logic_risk",
                    "severity": "low",
                    "line": getattr(node, 'lineno', 0),
                    "description": f"Function '{node.name}' does not explicitly return a value.",
                    "suggestion": "Add a return statement if a value is expected."
                })

            # Check for unreachable code
            for i, stmt in enumerate(node.body):
                if isinstance(stmt, (ast.Return, ast.Break, ast.Continue, ast.Raise)):
                    if i < len(node.body) - 1:
                        result["issues"].append({
                            "type": "bug",
                            "severity": "medium",
                            "line": getattr(node.body[i+1], 'lineno', 0),
                            "description": "Unreachable code detected after control flow statement.",
                            "suggestion": "Remove the unreachable code."
                        })

    # Style Analysis (PEP 8)
    lines = code.splitlines()
    for i, line in enumerate(lines, 1):
        if len(line) > 79:
            result["style_issues"].append(f"Line {i}: Line too long ({len(line)} > 79 characters).")

        # Basic naming check for functions/variables (snake_case)
        # This is a simplified regex check on the source line for demonstration
        match = re.search(r'def\s+([a-zA-Z0-9_]+)', line)
        if match:
            name = match.group(1)
            if not re.match(r'^[a-z_][a-z0-9_]*$', name):
                result["style_issues"].append(f"Line {i}: Function name '{name}' should be snake_case.")

