                        result["is_valid_syntax"] = False
                        result["overall_status"] = "syntax_error"
                        result["issues"].append({
                            "type": "syntax_error", "severity": "critical", "line": i,
                            "description": "Mismatched brackets.", "suggestion": "Ensure brackets match."
                        })
