                        "type": "syntax_error", "severity": "critical", "line": i,
                        "description": "Unmatched closing bracket.", "suggestion": "Check bracket pairing."
                    })
                else:
                    opening, _ = stack.pop()
                    if brackets[opening] != char:
                        result["is_valid_syntax"] = False
                        result["overall_status"] = "syntax_error"
                        result["issues"].append({
                            "type": "syntax_error", "severity": "critical", "line": i,
                            "description": "Mismatched brackets.", "suggestion": "Ensure brackets match."
                        })
    if stack:
        result["is_valid_syntax"] = False
        result["overall_status"] = "syntax_error"
        char, line_num = stack[-1]
        result["issues"].append({
            "type": "syntax_error", "severity": "critical", "line": line_num,
            "description": f"Unclosed bracket '{char}'.", "suggestion": "Close the bracket."
        })

    if not result["is_valid_syntax"]: return result

    # 2. Logic and Runtime Analysis
    defined_vars = {'print', 'len', 'range', 'int', 'str', 'list', 'dict', 'set', 'float', 'sum', 'max', 'min', 'open', 'True', 'False', 'None'}

    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        if not stripped: continue

        # Remove string literals to avoid false positives in variable detection
        # This handles basic '...' and "..."
        code_without_strings = re.sub(r'(".*?"|\'.*?\')', ' ', stripped)

        # Division by Zero
        if re.search(r'/\s*0(\.0+)?(\s*|$|#)', code_without_strings):
            result["issues"].append({
                "type": "runtime_risk", "severity": "high", "line": i,
                "description": "Potential division by zero detected.", "suggestion": "Ensure the divisor is not zero."
            })

        # Undefined Variables (Basic Assignment Tracking)
        assign_match = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)\s*=', code_without_strings.strip())
        if assign_match:
            defined_vars.add(assign_match.group(1))

        # Simple check for usage of undefined variables
        words = re.findall(r'\b([a-zA-Z_][a-zA-Z0-9_]*)\b', code_without_strings)
        for word in words:
            if word not in defined_vars and not re.match(r'^(def|if|else|elif|for|while|return|break|continue|pass|import|from|as|try|except|finally|class|with|in|and|or|not|lambda)', word):
                if not any(re.search(rf'def\s+[^:]*\b{word}\b', l) for l in lines):
                    result["issues"].append({
                        "type": "logic_risk", "severity": "medium", "line": i,
                        "description": f"Variable '{word}' may be undefined.", "suggestion": "Ensure the variable is defined."
                    })
                    defined_vars.add(word)

        # Unreachable Code
        if re.match(r'^(return|break|continue|raise)\b', stripped):
            if i < len(lines):
                next_line = lines[i].strip()
                if next_line and not next_line.startswith('#') and (not lines[i].startswith(line[:line.find(stripped)])):
                    result["issues"].append({
                        "type": "bug", "severity": "medium", "line": i + 1,
                        "description": "Unreachable code detected after control flow statement.", "suggestion": "Remove unreachable code."
                    })

    # 3. Function-specific analysis (Strict Mode)
    if strict_mode:
        for i, line in enumerate(lines, 1):
            if line.strip().startswith('def '):
                has_return = False
                indent = line[:line.find('def')]
                for next_line in lines[i:]:
                    if next_line.strip() and not next_line.startswith(indent + ' '):
                        break
                    if 'return' in next_line:
                        has_return = True
                        break
                if not has_return:
                    result["issues"].append({
                        "type": "logic_risk", "severity": "low", "line": i,
                        "description": "Function does not explicitly return a value.", "suggestion": "Add a return statement."
                    })

    # 4. Style Analysis (PEP 8)
    for i, line in enumerate(lines, 1):
        if len(line) > 79:
            result["style_issues"].append(f"Line {i}: Line too long ({len(line)} > 79 characters).")

        func_match = re.search(r'def\s+([a-zA-Z0-9_]+)', line)
        if func_match:
            name = func_match.group(1)
            if not re.match(r'^[a-z_][a-z0-9_]*$', name):
                result["style_issues"].append(f"Line {i}: Function name '{name}' should be snake_case.")

    # Final Aggregation
    result["bug_count"] = len([i for i in result["issues"] if i["type"] in ('bug', 'runtime_risk', 'logic_risk')])
    if result["issues"] or result["style_issues"]:
        result["overall_status"] = "issues_found"

    return result

